from admissions_records import *
def source(url,en,ru):return S(url,L(en,ru))
unknown={'satPolicy':'unknown','note':L('Academic entry depends on the school qualification and course. This language policy does not establish a universal SAT/ACT requirement or exemption.','Академический допуск зависит от школьной квалификации и программы. Языковая политика не устанавливает универсальную обязательность или освобождение от SAT/ACT.')}
def en(min,sections,variant='IELTS Academic',note=None):
 e={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':variant,'min':min,'sections':sections,'role':'admission'}}
 if note:e['note']=note
 return e

ss=[source('https://www.strath.ac.uk/studywithus/englishlanguagerequirements/','Strathclyde standard and faculty English requirements','Strathclyde: общие и факультетские требования английского')]
record('university-of-strathclyde',[route(id='standard-direct',label=L('Standard direct degree language rule — course exceptions apply','Стандартное языковое правило прямого приёма — есть исключения программ'),english=en(6.5,dict.fromkeys(['reading','writing','listening','speaking'],5.5),note=L('Some courses require different scores. This is the published standard, not a verified minimum for every course. Preparation courses have separate entry requirements.','У некоторых программ другие баллы. Это опубликованный стандарт, а не проверенный минимум каждой программы. У подготовительных курсов отдельные условия.')),academic=unknown,sources=ss),
 route(id='science-engineering-direct',label=L('Faculty of Science / undergraduate Engineering language rule','Языковое правило Faculty of Science / бакалавриата Engineering'),programmeIds=['computer-science','data-science','engineering','mathematics','biology'],english=en(6,dict.fromkeys(['reading','writing','listening','speaking'],5.5),note=L('Faculty standard only: verify your individual course. Science postgraduate research uses 6.5, not this undergraduate reference.','Только факультетский стандарт: проверьте свою программу. Для аспирантуры Science требуется 6,5, а не этот бакалаврский ориентир.')),academic=unknown,sources=ss)
], 'Separated standard 6.5 from Science/undergraduate Engineering 6.0 without transferring postgraduate rules.', ['Fall 2027 course-specific applicability, accepted alternative test scores, waivers and qualification-specific SAT rules need further official course verification.'])

ms=[source('https://www.mdx.ac.uk/international/entry-requirements-for-international-students/english-language-requirements-for-international-students/','Middlesex undergraduate column and exceptional courses','Middlesex: колонка бакалавриата и исключения')]
me=en(6,dict.fromkeys(['reading','writing','listening','speaking'],5.5),'IELTS online / paper; One Skill Retake accepted',L('General undergraduate column excludes exceptional courses. Nursing/Midwifery, Healthcare Science, Social Work and Veterinary Nursing have different requirements; do not use this 6.0 rule for them.','Общая бакалаврская колонка исключает особые программы. У Nursing/Midwifery, Healthcare Science, Social Work и Veterinary Nursing другие требования; правило 6,0 к ним не применяется.'))
me.update(toefl={'accepted':True,'scales':[{'period':'post2026','min':4,'sections':dict.fromkeys(['reading','writing','listening','speaking'],4)}]},alternatives=L('PTE Academic 59 in each component; Cambridge 168 overall/160 each; approved internal MDX test 3.0/2.5; listed IB/GCE and other certificates. TOEFL MyBest accepted. Some alternatives have Student Visa restrictions.','PTE Academic 59 в каждой секции; Cambridge общий 168/каждая 160; внутренний MDX 3,0/2,5; указанные IB/GCE и другие сертификаты. TOEFL MyBest принимается. У некоторых альтернатив ограничения Student Visa.'),waiver=L('Approved English-taught and assessed degree with NARIC/evidence; specified majority-English nationality with demonstrated competence; or approved pre-sessional completion. An arbitrary school MOI letter alone is not a blanket waiver.','Одобренная степень с преподаванием и оцениванием на английском с NARIC/документами; указанное англоязычное гражданство с подтверждённой компетенцией; либо одобренный pre-sessional. Произвольное школьное письмо MOI не является общим освобождением.'))
record('middlesex-university',[route(id='general-undergraduate',label=L('General undergraduate programmes — London; professional exceptions excluded','Общие программы бакалавриата — Лондон; профессиональные исключения не включены'),english=me,academic=unknown,sources=ms)], 'Read the undergraduate table column, kept each-skill minima and excluded graduate/professional-course thresholds.', ['Fall 2027-specific course acceptance, exact IELTS Academic wording and school-qualification SAT rules remain unconfirmed.'])

bs=[source('https://www.brookes.ac.uk/study/international-students/applying-to-arriving/how-to-apply/english-language-requirements','Oxford Brookes undergraduate and Foundation English requirements','Oxford Brookes: английский бакалавриата и Foundation')]
be=en(6,{'reading':6,'writing':6,'listening':5.5,'speaking':5.5},note=L('General undergraduate rule, excluding Law, Architecture, English Literature, health and other listed exceptions. Alternative tests are published in an IELTS-equivalence table; course and visa conditions matter.','Общее правило бакалавриата, кроме Law, Architecture, English Literature, медицинских и других перечисленных исключений. Альтернативные тесты опубликованы в таблице эквивалентов IELTS; важны программа и виза.'))
be.update(alternatives=L('Accepted alternatives include TOEFL (two scales), PTE, Cambridge, Duolingo and other named tests. One Skill Retake accepted. Pre-sessional English can start at 4.5; that is not degree entry.','Альтернативы включают TOEFL (две шкалы), PTE, Cambridge, Duolingo и другие названные тесты. One Skill Retake принимается. Pre-sessional может начинаться с 4,5; это не поступление на степень.'),waiver=L('Specified GCSE/GCE and country qualifications may satisfy English, assessed case by case. Visa applicants on pre-sessional/Foundation or a course below IELTS 6.0 need an approved UKVI SELT.','Могут подойти определённые GCSE/GCE и национальные квалификации, с индивидуальной оценкой. Для визы на pre-sessional/Foundation или программу ниже IELTS 6,0 нужен одобренный UKVI SELT.'))
record('oxford-brookes-university',[route(id='general-undergraduate',label=L('General direct undergraduate entry — listed exceptions excluded','Общий прямой приём на бакалавриат — перечисленные исключения не включены'),english=be,academic=unknown,sources=bs),
 route(id='international-foundation',kind='foundation',label=L('International Foundation Business/Technology or Arts/Humanities/Law','International Foundation Business/Technology либо Arts/Humanities/Law'),programmeIds=['business','economics','computer-science','arts','humanities','law'],english=en(5.5,dict.fromkeys(['reading','writing','listening','speaking'],5.5),note=L('Foundation, not direct bachelor admission. Built Environment and Life Sciences Foundation have a different 6.0 rule; visa SELT conditions also apply.','Foundation, не прямой приём на бакалавриат. У Built Environment и Life Sciences Foundation другое правило 6,0; также действуют визовые условия SELT.')),academic=unknown,sources=bs)
], 'Separated Foundation 5.5 from degree entry 6.0 and retained asymmetric Reading/Writing minima and programme exceptions.', ['Programme-specific Fall 2027 confirmation, academic qualification/SAT conditions and alternative-test table row values need separate verification.'])
finish()
